const fs = require\('fs'\);
const c = fs.readFileSync\('pages/dinein/index.vue', 'utf8'\);
const lines = c.split\('\\n'\);
let depth = 0;
const inTemplate = [];
let inScript = false;
let inStyle = false;
for \(let i = 0; i < Math.min\(lines.length, 195\); i++\) {
  const line = lines[i];
  if \(line.includes\('</template>'\)\) { inScript = true; continue; }
  if \(line.includes\('<style'\)\) { inStyle = true; continue; }
  if \(inScript || inStyle\) continue;

  const opens = \(line.match\(/<view[\\s>\\/]/g\) || []\).length;
  const closes = \(line.match\(/<\\/view>/g\) || []\).length;
  depth += opens - closes;
  if \(Math.abs\(depth\) > 0 || opens > 0 || closes > 0\) {
    console.log\(\(i+1\) + ': depth=' + depth + ' | ' + line.trim\(\).substring\(0, 80\)\);
  }
}
")

